#[doc = "A two-letter country code (ISO standard 3166). Required for users that are assigned licenses due to legal requirements to check for availability of services in countries/regions. Examples include: US, JP, and GB. Not nullable. Returned only on $select. Supports $filter (eq, ne, not, ge, le, in, startsWith, and eq on null values)."]
pub fn usage_location(&self) -> Result<Option<&str>, Error> {
    let val = self
        .properties
        .get("usageLocation")
        .ok_or(Error::NotFound)?;
    if val.is_null() {
        return Ok(None);
    }
    Ok(Some(val.as_str().ok_or_else(|| {
        Error::UnexpectedResponse(format!("{:?}", val))
    })?))
}
